cohen_d = function(x, y) {
  n1 = length(x)
  n2 = length(y)
  mean_diff = mean(x) - mean(y)
  pooled_sd = sqrt(((n1 - 1) * var(x) + (n2 - 1) * var(y)) / (n1 + n2 - 2))
  return(mean_diff / pooled_sd)
}

wilcoxon_r = function(stat, n) {
  return(stat / (n * (n + 1) / 2))
}

